package bookstore

import "sort"

// prices[k-1] is the cost, in cents, of a group of k distinct books.
var prices = []int{800, 1520, 2160, 2560, 3000}

// Cost returns the cheapest total price, in cents, for the books in the basket.
func Cost(books []int) int {
	counts := [5]int{}
	for _, book := range books {
		counts[book-1]++
	}

	sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })

	// The basket splits into counts[0] groups. Group j (j starting at 1) holds
	// one copy of every book that has at least j copies, so its natural size
	// is the number of books whose count is >= j.
	groups := make([]int, counts[0])
	for j := 1; j <= counts[0]; j++ {
		for _, c := range counts {
			if c >= j {
				groups[j-1]++
			}
		}
	}

	// A group of 5 plus a group of 3 costs 5160, while two groups of 4 cost
	// 5120, so convert as many (5,3) pairs as possible into (4,4) pairs.
	fives, threes := 0, 0
	for _, size := range groups {
		if size == 5 {
			fives++
		} else if size == 3 {
			threes++
		}
	}
	fiveLeft, threeLeft := fives, threes
	if threes < fives {
		fiveLeft = threes
	}
	for i := range groups {
		if groups[i] == 5 && fiveLeft > 0 {
			groups[i] = 4
			fiveLeft--
		} else if groups[i] == 3 && threeLeft > 0 {
			groups[i] = 4
			threeLeft--
		}
	}

	total := 0
	for _, size := range groups {
		total += prices[size-1]
	}
	return total
}

